import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { SelectBox } from "./select-box";
import { ComponentProps, useState } from "react";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

// The trigger is 100% wide, so every story renders the field in a capped-width block.
const fieldWidth = { maxWidth: "40rem" };
const fieldBottomMargin = { marginBottom: "15rem" };

// The selected value is controlled by the parent, so the stories keep it in local state and let
// onChange move it there while still reporting to the Actions panel.
const InteractiveSelectBox = (props: ComponentProps<typeof SelectBox>) => {
  const [value, setValue] = useState(props.value);
  return (
    <SelectBox
      {...props}
      value={value}
      onChange={(name, newValue) => {
        setValue(newValue);
        props.onChange?.(name, newValue);
      }}
    />
  );
};

const fourOptions = [
  { value: "adult", label: "Alternativ 1" },
  { value: "child", label: "Alternativ 2" },
  { value: "senior", label: "Alternativ 3" },
  { value: "student", label: "Alternativ 4" },
];

const meta = {
  title: "Primitives/Form Fields/Select Box",
  component: SelectBox,
  parameters: {
    docs: {
      description: {
        component:
          "Select field built on Radix Select. The trigger is a `combobox` button showing the selected option's " +
          "label or `notSelectedText`; the option list is rendered inline below the trigger (no portal) with a " +
          "staggered framer-motion animation and scroll buttons when it overflows. The form-field props fall back to " +
          "the matching `formField` property, so the form builder can drive it without repeating props. When " +
          "neither `notSelectedText` nor a `formField.placeholder` is given, the first option is selected by " +
          "default. `onChange(name, value)` fires only when a different, existing option is picked; the parent owns " +
          "the value.",
      },
    },
  },
  argTypes: {
    formField: { table: { disable: true } },
    inputRef: { table: { disable: true } },
    name: { table: { disable: true } },
    className: { table: { disable: true } },
    onChange: { table: { disable: true } },
    id: { table: { disable: true } },
    fieldTheme: { table: { disable: true } },
    onOpen: { table: { disable: true } },
    "data-testid": { table: { disable: true } },
  },
  args: {
    name: "ticketType",
    description: "Biljettyp",
    notSelectedText: "Välj ett alternativ",
    options: fourOptions,
    shouldShowCheckIcon: true,
    isDisabled: false,
    isRequired: false,
    onChange: fn(),
  },
  render: (args) => (
    <div style={fieldWidth}>
      <InteractiveSelectBox {...args} />
    </div>
  ),
} satisfies Meta<typeof SelectBox>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

/** Opens the list so the snapshot captures the options and the rotated chevron. */
export const Open: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("combobox"));
    // The options animate in via framer-motion (opacity starts at 0), so retry until visible.
    await waitFor(() => {
      expect(canvas.getByText("Alternativ 2")).toBeVisible();
    });
  },
};

export const VariantStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Field states" variantType="state">
      <Variant label="helperText">
        <div style={fieldWidth}>
          <SelectBox {...args} helperText="Barn är 3-11 år, senior från 65 år." />
        </div>
      </Variant>
      <Variant label="isRequired">
        <div style={fieldWidth}>
          <SelectBox {...args} isRequired />
        </div>
      </Variant>
      <Variant label="isDisabled">
        <div style={fieldWidth}>
          <SelectBox {...args} isDisabled />
        </div>
      </Variant>
      <Variant label="error (isValid false, errorText)">
        <div style={fieldWidth}>
          <SelectBox {...args} isRequired isValid={false} errorText="Detta fält är obligatoriskt" />
        </div>
      </Variant>
      <Variant label="preselected value">
        <div style={fieldWidth}>
          <SelectBox {...args} value="child" />
        </div>
      </Variant>
      <Variant label="shouldShowCheckIcon false with a value">
        <div style={fieldWidth}>
          <SelectBox {...args} value="child" shouldShowCheckIcon={false} />
        </div>
      </Variant>
      <Variant label="notSelectedText undefined (first option auto-selected)">
        <div style={fieldWidth}>
          <SelectBox {...args} notSelectedText={undefined} />
        </div>
      </Variant>
      <Variant label="20 options (closed here; open the list to see the scroll buttons)">
        <div style={{ ...fieldWidth, ...fieldBottomMargin }}>
          <SelectBox
            {...args}
            options={Array.from({ length: 20 }, (_, index) => ({
              value: `option-${index + 1}`,
              label: `Alternativ ${index + 1}`,
            }))}
          />
        </div>
      </Variant>
    </ShowcaseLayout>
  ),
};

const onChangeSpy = fn();

export const TestSelectOption: Story = {
  args: {
    onChange: onChangeSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("combobox"));
    await userEvent.click(await canvas.findByText("Alternativ 3"));
    await expect(onChangeSpy).toHaveBeenCalledTimes(1);
    await expect(onChangeSpy).toHaveBeenCalledWith("ticketType", "senior");
    // Picking an option closes the list and the trigger shows the new label.
    await waitFor(() => expect(canvas.queryByText("Alternativ 2")).not.toBeInTheDocument());
    await expect(canvas.getByRole("combobox")).toHaveTextContent("Alternativ 3");
  },
};
